mapper.insert:

    SELECT IFNULL(MAX(FILE_ID) + 1, 1) FROM tb_file A

INSERT INTO tb_file /*FileDAO.insertFile*/
       (
             FILE_ID         /*파일아이디*/
           , FILE_SN         /*파일순번*/
           , FILE_NM         /*원본파일명*/
           , RE_FILE_NM      /*저장 시 변경되는 파일명*/
           , FILE_TYPE       /*파일확장자*/
           , PATH            /*파일경로*/
           , SIZE            /*파일사이즈*/
           , CREAT_DTTM      /*등록자*/
           , CRTR_ID         /*등록날짜*/
           , UPDT_DTTM       /*수정자*/
           , UPDUSR_ID       /*수정날짜*/
       )
VALUES
       (
             #{fileId}
           , (SELECT IFNULL(MAX(B.FILE_SN) + 1, 1) FROM tb_file B WHERE FILE_ID = #{fileId})
           , #{orgFileNm}
           , #{reFileNm}
           , #{fileType}
           , #{filePath}
           , #{fileSize}
           , now()
           , #{crtrId}
           , now()
           , #{crtrId}
        )

