mapper.update:
UPDATE tb_file /*FileDAO.updateFile*/
   SET FILE_NM       = #{orgFileNm}
     , RE_FILE_NM    = #{reFileNm}
     , FILE_TYPE     = #{fileType}
     , PATH          = #{filePath}
     , SIZE          = #{fileSize}
     , UPDT_DTTM     = now()
     , UPDUSR_ID     = #{crtrId}
 WHERE FILE_ID       = #{fileId}
   AND FILE_SN       = #{fileSn}

